// This file is generated by AI.

// 路径 → Monaco 语言 id。
//
// **独立成一个不碰 monaco 的纯模块**有两个原因:
// * 它是"这个文件该用哪种语言"的唯一判据, 编辑器与差异选项卡都要用同一份 (复制一份必然漂移);
// * 纯函数可以在 node 里直接单测 —— 而它出过一次静默回归 (见下面 `languageForPath` 的注释),
//   仅靠类型检查与实机都发现不了。

/** WebGAL 场景脚本的语言 id (语义高亮、补全等全部 provider 都注册在它上面)。 */
export const LANGUAGE_ID = 'webgal';

/**
 * 路径 → Monaco 语言 id。
 *
 * **场景的判据必须同时认绝对路径与仓库相对路径**:
 * * 编辑器给的是绝对路径 —— `C:/proj/game/scene/1.txt` (Windows 反斜杠已归一);
 * * 差异选项卡给的是 **git 的仓库相对路径** —— `game/scene/1.txt`, **没有前导斜杠**。
 *
 * 这里曾经写作 `path.includes('/game/scene/')`, 只认第一种: 仓库相对路径永远不匹配, 于是
 * `.txt` 掉进扩展名的兜底分支变成 `plaintext`。场景的语义高亮 provider 只注册在 `webgal` 上,
 * 结果是**差异选项卡两侧一个字都不着色**, 而编辑器里一切正常 —— 没有任何报错。
 * 所以判据改成"`game/scene/` 出现在开头或某个 `/` 之后", 两种形态都覆盖。
 */
export function languageForPath(path: string): string {
  const normalized = path.replace(/\\/g, '/');
  if (/(^|\/)game\/scene\//i.test(normalized)) return LANGUAGE_ID;

  const extension = normalized.slice(normalized.lastIndexOf('.') + 1).toLowerCase();
  if (
    extension === 'json' ||
    extension === 'jsonl' ||
    extension === 'jsonc' ||
    extension === 'json5' ||
    extension === 'geojson' ||
    extension === 'webmanifest' ||
    extension === 'har' ||
    extension === 'map' ||
    extension === 'wmdl'
  )
    return 'json';
  if (extension === 'js' || extension === 'jsx' || extension === 'mjs' || extension === 'cjs') return 'javascript';
  if (extension === 'ts' || extension === 'tsx') return 'typescript';
  if (extension === 'css' || extension === 'scss' || extension === 'less') return extension;
  if (extension === 'html' || extension === 'htm') return 'html';
  if (extension === 'csv') return 'csv';
  if (extension === 'md' || extension === 'markdown') return 'markdown';
  return 'plaintext';
}
